import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { describe, it } from "@jest/globals";
import { buildExpectedIntegration, finalizedRuleIds, integratedTruthFiles, machineProposalSha256, packetSha256, preIntegrationCommit, responsePath, responseSha256, selectedRuleIds, truthFiles, validateIntegration, validateStoredResponse } from "../../../scripts/preverif/generate-rc5-maya-independent-review-batch4-integration";

const root = process.cwd();
const sha256 = (value: string | Buffer) => crypto.createHash("sha256").update(value).digest("hex");
const read = <T>(file: string): T => JSON.parse(fs.readFileSync(file, "utf8")) as T;
const equal = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);
const baseJson = <T>(file: string): T => JSON.parse(require("node:child_process").execFileSync("git", ["show", `${preIntegrationCommit}:${file}`]).toString("utf8")) as T;

describe("RC5-2 Maya independent review batch 4 integration", () => {
  it("validates the corrected response, exact seven IDs, hashes, schema, and evidence provenance", () => { const { response, packet } = validateStoredResponse(); assert.equal(sha256(fs.readFileSync(responsePath)), responseSha256); assert.equal(sha256(fs.readFileSync(path.join(root, "docs/roadmaps/interactive-evidence-review-mvp/rc/rc5/rc5-2-maya-independent-review-batch-4/review-packet.json"))), packetSha256); assert.equal(response.decisions.length, 7); assert.equal(new Set(response.decisions.map((d: any) => d.stableRuleId)).size, 7); assert.deepEqual(response.decisions.map((d: any) => d.stableRuleId), selectedRuleIds); assert.equal(response.sourceDocument.contentSha256, packet.sourceDocument.contentSha256); assert.equal(response.machineProposalRef.sha256, machineProposalSha256); });
  it("proves the stored integration is 48/10/58 and only the seven targets changed", () => { const { response, integrated, before } = buildExpectedIntegration(); const rows = [...integrated.values()].flatMap((truth: any) => truth.decisions); assert.equal(rows.filter((row: any) => row.reviewStatus === "REVIEWED").length, 48); assert.equal(rows.filter((row: any) => row.reviewStatus === "PROVISIONAL").length, 10); assert.equal(new Set(rows.map((row: any) => row.stableRuleId)).size, 58); assert.deepEqual(response.decisions.filter((d: any) => d.reviewStatus === "REVIEWED").map((d: any) => d.stableRuleId), finalizedRuleIds); assert.deepEqual(response.decisions.filter((d: any) => d.reviewStatus === "PROVISIONAL").map((d: any) => d.stableRuleId), ["Verra.AFOLU.VM0007.v1-8.R-2-0002", "Verra.AFOLU.VM0007.v1-8.R-2-0004", "Verra.AFOLU.VM0007.v1-8.R-2-0007", "Verra.AFOLU.VM0007.v1-8.R-4-0001"]); const targetSet = new Set(selectedRuleIds); for (const file of truthFiles) { const oldRows = new Map((before.get(file)!.decisions as any[]).map((row) => [row.stableRuleId, row])); const newRows = new Map((integrated.get(file)!.decisions as any[]).map((row) => [row.stableRuleId, row])); for (const [id, oldRow] of oldRows) if (!targetSet.has(id)) assert.deepEqual(newRows.get(id), oldRow, id); } });
  it("preserves machine truth, response bytes, manifests, and deterministic regeneration", () => { const machinePath = path.join(root, "tests/fixtures/preverif/maya-forest-corridor-redd-belize-live/machine-proposal.json"); assert.equal(sha256(fs.readFileSync(machinePath)), machineProposalSha256); assert.equal(validateIntegration(), true); const a = buildExpectedIntegration(); const b = buildExpectedIntegration(); assert.deepEqual([...a.integrated.entries()], [...b.integrated.entries()]); const manifest = read<any>(path.join(root, "docs/roadmaps/interactive-evidence-review-mvp/rc/rc5/rc5-2-maya-independent-review-batch-4/integration-manifest.json")); assert.deepEqual(manifest.integratedTruthFiles, integratedTruthFiles); assert.equal(manifest.inventory.after.reviewed, 48); assert.equal(manifest.inventory.after.provisional, 10); assert.equal(manifest.nonTargetRowsDeepCompared, true); assert.equal(manifest.machineTruthModified, false); assert.equal(manifest.correctedResponsePreservedByteForByte, true); for (const file of truthFiles) { const base = baseJson<any>(file); const actual = read<any>(path.join(root, file)); const targetSet = new Set(selectedRuleIds); for (const row of actual.decisions) if (!targetSet.has(row.stableRuleId)) assert.deepEqual(row, base.decisions.find((candidate: any) => candidate.stableRuleId === row.stableRuleId), `${file}:${row.stableRuleId}`); } });
});
